mapper.select:
select DISTINCT bv.* from book_voucher bv
LEFT JOIN book_voucher_record bvr on bvr.voucher_id = bv.voucher_id
where bv.del_flag = '0' and bvr.del_flag = '0'

    and bv.voucher_code like concat('%',#{params.voucherCode},'%')


    and bv.year_period >= #{params.startDate}


    and bv.year_period <= #{params.endDate}


    and bv.book_id = #{params.bookId}


    and bvr.subject_id = #{params.subjectId}


    and ${params.auxiliary}


    and bv.credit_total >= #{params.smallMoney}


    and bv.credit_total <= #{params.bigMoney}


    and bvr.summary like concat('%',#{params.summary},'%')


     and

        bv.voucher_id = #{id}


order by bv.voucher_date

    ${params.order}

,bv.create_time

    ${params.order}

limit #{page.pageStart},#{page.pageSize}

select count(DISTINCT bv.voucher_id) from book_voucher bv
LEFT JOIN book_voucher_record bvr on bvr.voucher_id = bv.voucher_id
where bv.del_flag = '0' and bvr.del_flag = '0'

    and bv.voucher_code like concat('%',#{voucherCode},'%')


    and bv.year_period >= #{startDate}


    and bv.year_period <= #{endDate}


    and bv.book_id = #{bookId}


    and bvr.subject_id = #{subjectId}


    and ${auxiliary}


    and bv.credit_total >= #{smallMoney}


    and bv.credit_total <= #{bigMoney}


    and

        bv.voucher_id = #{id}


order by bv.voucher_date

    ${order}


    and bvr.summary like concat('%',#{summary},'%')

SELECT * from book_voucher where del_flag = '0'

    and type_class_id = #{typeClassId}


    and voucher_type = #{voucherType}


    and book_id = #{bookId}


    and year_period = #{yearPeriod}

SELECT IFNULL(SUM(bvr.credit),0)-IFNULL(SUM(bvr.debit),0) from book_voucher_record bvr
LEFT JOIN book_voucher bv ON bv.voucher_id = bvr.voucher_id
LEFT JOIN book_subject bs ON bs.subject_id = bvr.subject_id
where bvr.del_flag = '0' and bv.del_flag = '0' and bv.book_id = #{bookId}
and bs.code LIKE CONCAT('',(SELECT code from book_subject where `name` = '本年利润' and book_id = #{bookId}) ,'%')
and bv.year_period = #{yearPeriod}
